mapper.select:
SELECT id, owner_id, kind, status, metadata_revision, current_version_id,
       version_number, created_at, updated_at
FROM knowledge_item WHERE owner_id = #{owner} AND id = #{id}

SELECT d.title, d.body, d.revision, d.saved_at
FROM knowledge_draft d JOIN knowledge_item i ON i.id = d.item_id
WHERE i.owner_id = #{owner} AND i.id = #{id}

SELECT i.id, i.kind, d.title, i.status, i.metadata_revision, i.version_number, i.updated_at
FROM knowledge_item i JOIN knowledge_draft d ON d.item_id = i.id
WHERE i.owner_id = #{owner} AND i.status = #{status}
AND i.kind = #{kind}
AND d.title LIKE #{pattern} ESCAPE '!'
AND i.id > #{cursor}
ORDER BY i.id ASC LIMIT #{limit}

SELECT id, version_number, title, created_at FROM knowledge_version
WHERE owner_id = #{owner} AND item_id = #{id}
AND version_number < #{before}
ORDER BY version_number DESC LIMIT #{limit}

SELECT id, source_id, target_id, relation_type FROM knowledge_relation
WHERE owner_id = #{owner} AND source_id IN
#{id}
AND target_id IN
#{id}
ORDER BY id LIMIT #{limit}

mapper.update:
UPDATE knowledge_draft d JOIN knowledge_item i ON i.id = d.item_id
SET d.title = #{title}, d.body = #{body}, d.revision = d.revision + 1, d.saved_at = #{now}
WHERE i.owner_id = #{owner} AND i.id = #{id} AND i.status = 'ACTIVE' AND d.revision = #{expectedRevision}

UPDATE knowledge_draft d JOIN knowledge_item i ON i.id = d.item_id
SET d.revision = d.revision + 1, d.saved_at = #{now}
WHERE i.owner_id = #{owner} AND i.id = #{id} AND i.status = 'ACTIVE' AND d.revision = #{expectedRevision}

UPDATE knowledge_item SET current_version_id = #{versionId}, version_number = #{number},
  metadata_revision = metadata_revision + 1, updated_at = #{now}
WHERE owner_id = #{owner} AND id = #{id} AND status = 'ACTIVE' AND metadata_revision = #{expectedRevision}
